    [DllImport(LibraryName, EntryPoint = "meshopt_opacityMapMeasure", CallingConvention = CallingConvention.Cdecl, ExactSpelling = true)]
    public static extern nuint OpacityMapMeasure(byte* levels, uint* sources, int* omm_indices, uint* indices, nuint index_count, float* vertex_uvs, nuint vertex_count, nuint vertex_uvs_stride, uint texture_width, uint texture_height, int max_level, float target_edge);

    /// <summary>Opacity micromap generator (rasterize) Rasterizes opacity state for a single triangle entry by sampling the alpha texture, using bilinear filtering and 0.5 alpha cutoff.</summary>
    [DllImport(LibraryName, EntryPoint = "meshopt_opacityMapRasterize", CallingConvention = CallingConvention.Cdecl, ExactSpelling = true)]
    public static extern void OpacityMapRasterize(byte* result, int level, int states, float* uv0, float* uv1, float* uv2, byte* texture_data, nuint texture_stride, nuint texture_pitch, uint texture_width, uint texture_height);

    /// <summary>Meshlet optimizer Reorders meshlet vertices and triangles to maximize locality which can improve rasterizer throughput or ray tracing performance when using fast-build modes.</summary>
    [DllImport(LibraryName, EntryPoint = "meshopt_optimizeMeshlet", CallingConvention = CallingConvention.Cdecl, ExactSpelling = true)]
    public static extern void OptimizeMeshlet(uint* meshlet_vertices, byte* meshlet_triangles, nuint triangle_count, nuint vertex_count);

    /// <summary>Meshlet optimizer Reorders meshlet vertices and triangles to maximize locality, with higher levels resulting in smaller compressed size at the cost of optimization time. At level 0 the result is equivalent to meshopt_optimizeMeshlet; levels &gt;= 1 may rotate triangle corners to improve compression (which can change provoking vertex and affect OMM data).</summary>
    [DllImport(LibraryName, EntryPoint = "meshopt_optimizeMeshletLevel", CallingConvention = CallingConvention.Cdecl, ExactSpelling = true)]
    public static extern void OptimizeMeshletLevel(uint* meshlet_vertices, nuint vertex_count, byte* meshlet_triangles, nuint triangle_count, int level);

    /// <summary>Overdraw optimizer Reorders indices to reduce the number of GPU vertex shader invocations and the pixel overdraw If index buffer contains multiple ranges for multiple draw calls, this function needs to be called on each range individually.</summary>
    [DllImport(LibraryName, EntryPoint = "meshopt_optimizeOverdraw", CallingConvention = CallingConvention.Cdecl, ExactSpelling = true)]
    public static extern void OptimizeOverdraw(uint* destination, uint* indices, nuint index_count, float* vertex_positions, nuint vertex_count, nuint vertex_positions_stride, float threshold);

    /// <summary>Vertex transform cache optimizer Reorders indices to reduce the number of GPU vertex shader invocations If index buffer contains multiple ranges for multiple draw calls, this function needs to be called on each range individually.</summary>
    [DllImport(LibraryName, EntryPoint = "meshopt_optimizeVertexCache", CallingConvention = CallingConvention.Cdecl, ExactSpelling = true)]
    public static extern void OptimizeVertexCache(uint* destination, uint* indices, nuint index_count, nuint vertex_count);

    /// <summary>Vertex transform cache optimizer for FIFO caches Reorders indices to reduce the number of GPU vertex shader invocations Generally takes ~3x less time to optimize meshes but produces inferior results compared to meshopt_optimizeVertexCache If index buffer contains multiple ranges for multiple draw calls, this function needs to be called on each range individually.</summary>
    [DllImport(LibraryName, EntryPoint = "meshopt_optimizeVertexCacheFifo", CallingConvention = CallingConvention.Cdecl, ExactSpelling = true)]
    public static extern void OptimizeVertexCacheFifo(uint* destination, uint* indices, nuint index_count, nuint vertex_count, uint cache_size);

    /// <summary>Vertex transform cache optimizer for strip-like caches Produces inferior results to meshopt_optimizeVertexCache from the GPU vertex cache perspective However, the resulting index order is more optimal if the goal is to reduce the triangle strip length or improve compression efficiency</summary>
    [DllImport(LibraryName, EntryPoint = "meshopt_optimizeVertexCacheStrip", CallingConvention = CallingConvention.Cdecl, ExactSpelling = true)]
    public static extern void OptimizeVertexCacheStrip(uint* destination, uint* indices, nuint index_count, nuint vertex_count);

    /// <summary>Vertex fetch cache optimizer Reorders vertices and changes indices to reduce the amount of GPU memory fetches during vertex processing Returns the number of unique vertices, which is the same as input vertex count unless some vertices are unused This function works for a single vertex stream; for multiple vertex streams, use meshopt_optimizeVertexFetchRemap + meshopt_remapVertexBuffer for each stream.</summary>
    [DllImport(LibraryName, EntryPoint = "meshopt_optimizeVertexFetch", CallingConvention = CallingConvention.Cdecl, ExactSpelling = true)]
    public static extern nuint OptimizeVertexFetch(void* destination, uint* indices, nuint index_count, void* vertices, nuint vertex_count, nuint vertex_size);

    /// <summary>Vertex fetch cache optimizer Generates vertex remap to reduce the amount of GPU memory fetches during vertex processing Returns the number of unique vertices, which is the same as input vertex count unless some vertices are unused The resulting remap table should be used to reorder vertex/index buffers using meshopt_remapVertexBuffer/meshopt_remapIndexBuffer</summary>
    [DllImport(LibraryName, EntryPoint = "meshopt_optimizeVertexFetchRemap", CallingConvention = CallingConvention.Cdecl, ExactSpelling = true)]
    public static extern nuint OptimizeVertexFetchRemap(uint* destination, uint* indices, nuint index_count, nuint vertex_count);

    /// <summary>Cluster partitioner Partitions clusters into groups of similar size, prioritizing grouping clusters that share vertices or are close to each other. When vertex positions are not provided, only clusters that share vertices will be grouped together, which may result in small partitions for some inputs.</summary>
    [DllImport(LibraryName, EntryPoint = "meshopt_partitionClusters", CallingConvention = CallingConvention.Cdecl, ExactSpelling = true)]
    public static extern nuint PartitionClusters(uint* destination, uint* cluster_indices, nuint total_index_count, uint* cluster_index_counts, nuint cluster_count, float* vertex_positions, nuint vertex_count, nuint vertex_positions_stride, nuint target_partition_size);

    /// <summary>Quantize a float into a floating point value with a limited number of significant mantissa bits, preserving the IEEE-754 fp32 binary representation Preserves infinities/NaN, flushes denormals to zero, rounds to nearest Assumes N is in a valid mantissa precision range, which is 1..23</summary>
    [DllImport(LibraryName, EntryPoint = "meshopt_quantizeFloat", CallingConvention = CallingConvention.Cdecl, ExactSpelling = true)]
    public static extern float QuantizeFloat(float v, int N);

    /// <summary>Quantize a float into half-precision (as defined by IEEE-754 fp16) floating point value Generates +-inf for overflow, preserves NaN, flushes denormals to zero, rounds to nearest Representable magnitude range: [6e-5; 65504] Maximum relative reconstruction error: 5e-4</summary>
    [DllImport(LibraryName, EntryPoint = "meshopt_quantizeHalf", CallingConvention = CallingConvention.Cdecl, ExactSpelling = true)]
    public static extern ushort QuantizeHalf(float v);

    /// <summary>Generate index buffer from the source index buffer and remap table generated by meshopt_generateVertexRemap</summary>
    [DllImport(LibraryName, EntryPoint = "meshopt_remapIndexBuffer", CallingConvention = CallingConvention.Cdecl, ExactSpelling = true)]
    public static extern void RemapIndexBuffer(uint* destination, uint* indices, nuint index_count, uint* remap);

    /// <summary>Generates vertex buffer from the source vertex buffer and remap table generated by meshopt_generateVertexRemap</summary>
    [DllImport(LibraryName, EntryPoint = "meshopt_remapVertexBuffer", CallingConvention = CallingConvention.Cdecl, ExactSpelling = true)]
    public static extern void RemapVertexBuffer(void* destination, void* vertices, nuint vertex_count, nuint vertex_size, uint* remap);

    /// <summary>Experimental: Voxel remesher Generates a new mesh that approximates or refines the original mesh, attempting to preserve mesh appearance at a given voxel resolution. The original topology is not preserved; features that are closer than the voxel size may be merged, and small gaps in the original mesh may be closed. Returns the number of triangles in the new mesh, with destination containing a vertex position for each triangle corner.</summary>
    [DllImport(LibraryName, EntryPoint = "meshopt_remesh", CallingConvention = CallingConvention.Cdecl, ExactSpelling = true)]
    public static extern nuint Remesh(float* destination, nuint max_triangle_count, uint* indices, nuint index_count, float* vertex_positions, nuint vertex_count, nuint vertex_positions_stride, int resolution, uint options);

    /// <summary>Set allocation callbacks These callbacks will be used instead of the default operator new/operator delete for all temporary allocations in the library. Note that all algorithms only allocate memory for temporary use. allocate/deallocate are always called in a stack-like order - last pointer to be allocated is deallocated first. This function is not thread safe and must not be called concurrently with any other meshopt_ function.</summary>
    [DllImport(LibraryName, EntryPoint = "meshopt_setAllocator", CallingConvention = CallingConvention.Cdecl, ExactSpelling = true)]
    public static extern void SetAllocator(delegate* unmanaged[Cdecl]<nuint, void*> allocate, delegate* unmanaged[Cdecl]<void*, void> deallocate);

    /// <summary>Mesh simplifier Reduces the number of triangles in the mesh, attempting to preserve mesh appearance as much as possible The algorithm tries to preserve mesh topology and can stop short of the target goal based on topology constraints or target error. If not all attributes from the input mesh are needed, it's recommended to reindex the mesh without them prior to simplification. Returns the number of indices after simplification, with destination containing new index data</summary>
    [DllImport(LibraryName, EntryPoint = "meshopt_simplify", CallingConvention = CallingConvention.Cdecl, ExactSpelling = true)]
    public static extern nuint Simplify(uint* destination, uint* indices, nuint index_count, float* vertex_positions, nuint vertex_count, nuint vertex_positions_stride, nuint target_index_count, float target_error, uint options, float* result_error);

    /// <summary>Point cloud simplifier Reduces the number of points in the cloud to reach the given target Returns the number of points after simplification, with destination containing new index data The resulting index buffer references vertices from the original vertex buffer. If the original vertex data isn't needed, creating a compact vertex buffer using meshopt_optimizeVertexFetch is recommended.</summary>
    [DllImport(LibraryName, EntryPoint = "meshopt_simplifyPoints", CallingConvention = CallingConvention.Cdecl, ExactSpelling = true)]
    public static extern nuint SimplifyPoints(uint* destination, float* vertex_positions, nuint vertex_count, nuint vertex_positions_stride, float* vertex_colors, nuint vertex_colors_stride, float color_weight, nuint target_vertex_count);

    /// <summary>Mesh simplifier (pruner) Reduces the number of triangles in the mesh by removing small isolated parts of the mesh Returns the number of indices after simplification, with destination containing new index data The resulting index buffer references vertices from the original vertex buffer. If the original vertex data isn't needed, creating a compact vertex buffer using meshopt_optimizeVertexFetch is recommended.</summary>
    [DllImport(LibraryName, EntryPoint = "meshopt_simplifyPrune", CallingConvention = CallingConvention.Cdecl, ExactSpelling = true)]
    public static extern nuint SimplifyPrune(uint* destination, uint* indices, nuint index_count, float* vertex_positions, nuint vertex_count, nuint vertex_positions_stride, float target_error);

    /// <summary>Returns the error scaling factor used by the simplifier to convert between absolute and relative extents</summary>
    [DllImport(LibraryName, EntryPoint = "meshopt_simplifyScale", CallingConvention = CallingConvention.Cdecl, ExactSpelling = true)]
    public static extern float SimplifyScale(float* vertex_positions, nuint vertex_count, nuint vertex_positions_stride);

    /// <summary>Mesh simplifier (sloppy) Reduces the number of triangles in the mesh, sacrificing mesh appearance for simplification performance The algorithm doesn't preserve mesh topology but can stop short of the target goal based on target error. Returns the number of indices after simplification, with destination containing new index data The resulting index buffer references vertices from the original vertex buffer. If the original vertex data isn't needed, creating a compact vertex buffer using meshopt_optimizeVertexFetch is recommended.</summary>
    [DllImport(LibraryName, EntryPoint = "meshopt_simplifySloppy", CallingConvention = CallingConvention.Cdecl, ExactSpelling = true)]
    public static extern nuint SimplifySloppy(uint* destination, uint* indices, nuint index_count, float* vertex_positions, nuint vertex_count, nuint vertex_positions_stride, byte* vertex_lock, nuint target_index_count, float target_error, float* result_error);

    /// <summary>Mesh simplifier with attribute metric Reduces the number of triangles in the mesh, attempting to preserve mesh appearance as much as possible. Similar to meshopt_simplify, but incorporates attribute values into the error metric used to prioritize simplification order. The algorithm tries to preserve mesh topology and can stop short of the target goal based on topology constraints or target error. If not all attributes from the input mesh are needed, it's recommended to reindex the mesh without them prior to simplification. Returns the number of indices after simplification, with destination containing new index data</summary>
    [DllImport(LibraryName, EntryPoint = "meshopt_simplifyWithAttributes", CallingConvention = CallingConvention.Cdecl, ExactSpelling = true)]
    public static extern nuint SimplifyWithAttributes(uint* destination, uint* indices, nuint index_count, float* vertex_positions, nuint vertex_count, nuint vertex_positions_stride, float* vertex_attributes, nuint vertex_attributes_stride, float* attribute_weights, nuint attribute_count, byte* vertex_lock, nuint target_index_count, float target_error, uint options, float* result_error);

    /// <summary>Mesh simplifier with position/attribute update Reduces the number of triangles in the mesh, attempting to preserve mesh appearance as much as possible. Similar to meshopt_simplifyWithAttributes, but destructively updates positions and attribute values for optimal appearance. The algorithm tries to preserve mesh topology and can stop short of the target goal based on topology constraints or target error. If not all attributes from the input mesh are needed, it's recommended to reindex the mesh without them prior to simplification. Returns the number of indices after simplification, indices are destructively updated with new index data</summary>
    [DllImport(LibraryName, EntryPoint = "meshopt_simplifyWithUpdate", CallingConvention = CallingConvention.Cdecl, ExactSpelling = true)]
    public static extern nuint SimplifyWithUpdate(uint* indices, nuint index_count, float* vertex_positions, nuint vertex_count, nuint vertex_positions_stride, float* vertex_attributes, nuint vertex_attributes_stride, float* attribute_weights, nuint attribute_count, byte* vertex_lock, nuint target_index_count, float target_error, uint options, float* result_error);

    /// <summary>Spatial clusterizer Reorders points into clusters optimized for spatial locality, and generates a new index buffer. Ensures the output can be split into cluster_size chunks where each chunk has good positional locality. Only the last chunk will be smaller than cluster_size.</summary>
    [DllImport(LibraryName, EntryPoint = "meshopt_spatialClusterPoints", CallingConvention = CallingConvention.Cdecl, ExactSpelling = true)]
    public static extern void SpatialClusterPoints(uint* destination, float* vertex_positions, nuint vertex_count, nuint vertex_positions_stride, nuint cluster_size);

    /// <summary>Spatial sorter Generates a remap table that can be used to reorder points for spatial locality. Resulting remap table maps old vertices to new vertices and can be used in meshopt_remapVertexBuffer.</summary>
    [DllImport(LibraryName, EntryPoint = "meshopt_spatialSortRemap", CallingConvention = CallingConvention.Cdecl, ExactSpelling = true)]
    public static extern void SpatialSortRemap(uint* destination, float* vertex_positions, nuint vertex_count, nuint vertex_positions_stride);

    /// <summary>Spatial sorter Reorders triangles for spatial locality, and generates a new index buffer. The resulting index buffer can be used with other functions like optimizeVertexCache.</summary>
    [DllImport(LibraryName, EntryPoint = "meshopt_spatialSortTriangles", CallingConvention = CallingConvention.Cdecl, ExactSpelling = true)]
    public static extern void SpatialSortTriangles(uint* destination, uint* indices, nuint index_count, float* vertex_positions, nuint vertex_count, nuint vertex_positions_stride);

    /// <summary>Mesh stripifier Converts a previously vertex cache optimized triangle list to triangle strip, stitching strips using restart index or degenerate triangles Returns the number of indices in the resulting strip, with destination containing new index data For maximum efficiency the index buffer being converted has to be optimized for vertex cache first. Using restart indices can result in ~10% smaller index buffers, but on some GPUs restart indices may result in decreased performance.</summary>
    [DllImport(LibraryName, EntryPoint = "meshopt_stripify", CallingConvention = CallingConvention.Cdecl, ExactSpelling = true)]
    public static extern nuint Stripify(uint* destination, uint* indices, nuint index_count, nuint vertex_count, uint restart_index);

    [DllImport(LibraryName, EntryPoint = "meshopt_stripifyBound", CallingConvention = CallingConvention.Cdecl, ExactSpelling = true)]
    public static extern nuint StripifyBound(nuint index_count);

    /// <summary>Mesh unstripifier Converts a triangle strip to a triangle list Returns the number of indices in the resulting list, with destination containing new index data</summary>
    [DllImport(LibraryName, EntryPoint = "meshopt_unstripify", CallingConvention = CallingConvention.Cdecl, ExactSpelling = true)]
    public static extern nuint Unstripify(uint* destination, uint* indices, nuint index_count, uint restart_index);

    [DllImport(LibraryName, EntryPoint = "meshopt_unstripifyBound", CallingConvention = CallingConvention.Cdecl, ExactSpelling = true)]
    public static extern nuint UnstripifyBound(nuint index_count);
}
